insert into questions (exam_type, year, question_no, field_tags, difficulty, body, choices, official_answer, explanation, source) values
('D3', 'gen-batch-003', 61, ARRAY['network']::text[], 2, '世界中のユーザーに静的コンテンツ(画像・CSS・JS)を低遅延で配信し、オリジンの S3 負荷も下げたい。適切なサービスはどれか。', '{"ア":"S3 バケットを全リージョンに手動で複製する","イ":"EC2 に Nginx を立ててキャッシュサーバーにする","ウ":"Route 53 の地理的近接性ルーティングだけを使う","エ":"Amazon CloudFront を S3 オリジンの前段に配置する"}'::jsonb, 'エ', 'CloudFront は世界中のエッジロケーションにコンテンツをキャッシュし、ユーザー最寄りのエッジから配信して遅延とオリジン負荷を下げる。OAC で S3 を非公開のままにできる。DNS ルーティングは配信そのものを高速化しない。', 'generated'),
('D3', 'gen-batch-003', 62, ARRAY['database']::text[], 2, '読み取りが非常に多い RDS で、読み取りクエリによってプライマリの CPU が逼迫している。書き込み性能は十分。適切な対策はどれか。', '{"ア":"マルチ AZ 配置に変更する","イ":"リードレプリカを作成し、読み取りクエリをレプリカのエンドポイントへ振り向ける","ウ":"インスタンスを再起動する","エ":"自動バックアップの保持期間を延ばす"}'::jsonb, 'イ', 'リードレプリカは非同期複製された読み取り専用インスタンスで、参照系をオフロードできる。アプリを読み書きで接続先を分ける。マルチ AZ のスタンバイは読み取りに使えない(HA 目的)。', 'generated'),
('D3', 'gen-batch-003', 63, ARRAY['database']::text[], 3, 'DynamoDB でミリ秒未満の読み取り応答が必要になった。ホットなアイテムへの読み取りが集中している。適切な対策はどれか。', '{"ア":"テーブルのプロビジョンド読み取りキャパシティを 10 倍にする","イ":"グローバルテーブルを有効にする","ウ":"DynamoDB Accelerator(DAX)をインメモリキャッシュとして導入する","エ":"TTL を設定して古い項目を削除する"}'::jsonb, 'ウ', 'DAX は DynamoDB 専用のライトスルー型インメモリキャッシュで、キャッシュヒット時はマイクロ秒台の応答になる。読み取り集中の緩和にも効く。キャパシティ増加はコスト増でレイテンシは根本的に下がらない。', 'generated'),
('D3', 'gen-batch-003', 64, ARRAY['database']::text[], 2, 'リレーショナル DB の前段にキャッシュを置いてクエリ結果や頻繁に参照される値を高速に返したい。汎用的なマネージドキャッシュはどれか。', '{"ア":"Amazon ElastiCache(Redis または Memcached)","イ":"Amazon S3","ウ":"Amazon Athena","エ":"AWS Glue"}'::jsonb, 'ア', 'ElastiCache はマネージドの Redis / Memcached で、DB クエリ結果、セッション、リーダーボードなどをインメモリで保持し、レイテンシとバックエンド負荷を下げる。Redis は永続化・レプリケーション・データ構造が豊富、Memcached は単純でスケールアウト向き。', 'generated'),
('D3', 'gen-batch-003', 65, ARRAY['compute']::text[], 2, '機械学習の推論で大量の並列行列演算を行う。最も適した EC2 インスタンスファミリーはどれか。', '{"ア":"汎用インスタンス(T 系)","イ":"ストレージ最適化インスタンス(I 系)","ウ":"メモリ最適化インスタンス(R 系)","エ":"GPU 搭載インスタンス(P 系 / G 系)"}'::jsonb, 'エ', '行列演算・ディープラーニングは GPU が圧倒的に速い。P 系は学習、G 系は推論やグラフィックスに向く。I 系は高 IOPS ローカルストレージ、R 系は大容量メモリ(インメモリ DB 等)、T 系はバースト可能な汎用で軽負荷向き。', 'generated'),
('D3', 'gen-batch-003', 66, ARRAY['compute']::text[], 3, 'T 系(バースタブル)インスタンスで、平常時は低負荷だが日次バッチ時に長時間 CPU を 100% 使う。バッチ中に性能が落ちる現象への対策はどれか。', '{"ア":"インスタンスを停止・起動してクレジットをリセットする","イ":"EBS のスループットを上げる","ウ":"Unlimited モードを有効にするか、M 系など固定性能のインスタンスに変更する","エ":"セキュリティグループの制限を緩める"}'::jsonb, 'ウ', 'T 系は CPU クレジットを消費してバーストし、枯渇するとベースライン性能に制限される。恒常的に高負荷なら Unlimited モード(追加課金でバースト継続)か、M/C 系の固定性能インスタンスへ移行するのが適切。', 'generated'),
('D3', 'gen-batch-003', 67, ARRAY['storage']::text[], 3, 'データベース用の EBS ボリュームで、安定して高い IOPS(数万)と低レイテンシが求められ、ミッションクリティカルである。適切なボリュームタイプはどれか。', '{"ア":"プロビジョンド IOPS SSD(io2 Block Express / io2)","イ":"汎用 SSD(gp2)","ウ":"スループット最適化 HDD(st1)","エ":"Cold HDD(sc1)"}'::jsonb, 'ア', 'io2 / io2 Block Express は IOPS を明示的にプロビジョンでき、高耐久性・一貫した低レイテンシで I/O 集約型 DB に適する。gp3/gp2 は汎用で上限あり。st1/sc1 は大容量シーケンシャル向けの HDD で低 IOPS。', 'generated'),
('D3', 'gen-batch-003', 68, ARRAY['storage']::text[], 2, '一時的なスクラッチ領域として非常に高速なローカルディスク I/O が必要だが、インスタンス停止でデータが消えても構わない。適切な選択肢はどれか。', '{"ア":"gp3 の EBS ボリュームを使う","イ":"インスタンスストア(エフェメラルストレージ)を使う","ウ":"EFS をマウントする","エ":"S3 をファイルシステムとしてマウントする"}'::jsonb, 'イ', 'インスタンスストアは物理ホスト直結のブロックストレージで非常に高速だが、停止・終了・ホスト障害で内容が失われる。キャッシュ、バッファ、スクラッチなど揮発してよいデータに最適。永続化が要るなら EBS。', 'generated'),
('D3', 'gen-batch-003', 69, ARRAY['network']::text[], 3, 'TCP/UDP を用いるグローバルなゲームサーバーで、エニーキャスト IP による最寄りエッジ取り込みと AWS バックボーン経由の低ジッタ通信、リージョン間の高速フェイルオーバーが必要。適切なサービスはどれか。', '{"ア":"Amazon CloudFront","イ":"Route 53 レイテンシールーティング","ウ":"AWS Global Accelerator","エ":"AWS Direct Connect"}'::jsonb, 'ウ', 'Global Accelerator は 2 つの固定エニーキャスト IP を提供し、ユーザーを最寄りのエッジから AWS バックボーンに載せて、TCP/UDP 双方の非 HTTP ワークロードを高速・安定化する。エンドポイント異常時は数十秒でリージョン切替。CloudFront は HTTP キャッシュ配信向け。', 'generated'),
('D3', 'gen-batch-003', 70, ARRAY['performance']::text[], 2, '動的コンテンツ(API レスポンス)は CloudFront で高速化できないという思い込みがある。正しい説明はどれか。', '{"ア":"動的コンテンツもエッジで TLS 終端し、AWS バックボーン経由でオリジンへ到達するため遅延を削減できる","イ":"CloudFront は静的ファイルしか通せない","ウ":"動的コンテンツは必ずキャッシュされ、古い応答が返る","エ":"動的コンテンツを通すとオリジンが二重課金される"}'::jsonb, 'ア', 'CloudFront はキャッシュしない(TTL=0 やキャッシュポリシー無効)動的リクエストでも、エッジでの接続確立・TLS 終端・最適化された経路により往復遅延を短縮できる。キャッシュの有無はビヘイビアごとに制御可能。', 'generated'),
('D3', 'gen-batch-003', 71, ARRAY['compute']::text[], 2, '急激なトラフィック変動があり、サーバー管理をなくして「実行時間分だけ」課金される構成で API を提供したい。適切な組み合わせはどれか。', '{"ア":"単一の大型 EC2 インスタンス + cron","イ":"Auto Scaling を無効化した EC2 1 台","ウ":"オンプレミスのサーバーを増設する","エ":"Amazon API Gateway + AWS Lambda"}'::jsonb, 'エ', 'API Gateway + Lambda はサーバーレスで、リクエスト量に応じて自動スケールし、アイドル時は課金されない。急峻なスパイクにも即応する。EC2 固定台数は過剰/不足のリスクとサーバー管理が残る。', 'generated'),
('D3', 'gen-batch-003', 72, ARRAY['storage']::text[], 3, 'S3 で秒間数千を超える PUT/GET を安定して処理したい。現在のプレフィックス設計を見直す必要があるか。', '{"ア":"S3 のリクエストレートはバケットあたり固定で、これ以上は上げられない","イ":"S3 はプレフィックスごとに高いリクエストレートへ自動スケールするため、キーをプレフィックスで分散させると並列性を高められる","ウ":"バケットを 100 個に分割しないと高スループットは出ない","エ":"リクエストを増やすには事前に AWS へ物理容量を予約する必要がある"}'::jsonb, 'イ', '現在の S3 は 1 プレフィックスあたり 3,500 PUT/COPY/POST/DELETE・5,500 GET/HEAD 毎秒をサポートし、プレフィックスを増やせば線形にスケールする。キー先頭にハッシュや日付区切りを入れて分散するのが定石。', 'generated'),
('D3', 'gen-batch-003', 73, ARRAY['database']::text[], 3, '分析用に大量データへ複雑な集計 SQL を実行するとトランザクション用の RDS が重くなる。ペタバイト級にも対応できる分析用データウェアハウスはどれか。', '{"ア":"Amazon RDS のインスタンスサイズを最大にする","イ":"Amazon Redshift","ウ":"Amazon ElastiCache","エ":"Amazon DynamoDB"}'::jsonb, 'イ', 'Redshift は列指向・MPP のデータウェアハウスで、大規模な集計・結合クエリに最適化されている。OLTP 用 RDS から分析ワークロードを分離できる。DynamoDB は KVS で複雑な集計 SQL には不向き、ElastiCache はキャッシュ。', 'generated'),
('D3', 'gen-batch-003', 74, ARRAY['integration']::text[], 2, 'ピーク時に Web 層からの書き込みで RDS が詰まる。ユーザー体験を保ちつつ DB を保護するアーキテクチャはどれか。', '{"ア":"RDS への同時接続数制限を撤廃する","イ":"Web インスタンス数だけを増やす","ウ":"書き込みを SQS にバッファし、コンシューマが DB の処理能力に合わせて一定レートで書き込む(キューによる負荷平準化)","エ":"DB のタイムアウト値を無限にする"}'::jsonb, 'ウ', 'キューを挟むと、スパイクはキューが吸収し、コンシューマがバックエンドの限界に合わせて流量制御(スロットリング)できる。Web 層だけ増やすと DB への同時負荷が増えて悪化する。負荷平準化(queue-based load leveling)が定石。', 'generated'),
('D3', 'gen-batch-003', 75, ARRAY['network']::text[], 2, '同一 VPC 内で HPC ワークロードのノード間通信に、最低レイテンシと高いパケット毎秒性能が必要。適切な設定はどれか。', '{"ア":"クラスタープレイスメントグループに配置し、拡張ネットワーキング(ENA / EFA)を有効にする","イ":"各インスタンスを別々の AZ に分散配置する","ウ":"スプレッドプレイスメントグループに配置する","エ":"パブリック IP 経由で通信させる"}'::jsonb, 'ア', 'クラスタープレイスメントグループは単一 AZ 内でインスタンスを近接配置し、低レイテンシ・高スループットのノード間通信を実現する。EFA は HPC/ML 向けの OS バイパス通信。AZ 分散やスプレッドは可用性向けでレイテンシは増える。', 'generated'),
('D3', 'gen-batch-003', 76, ARRAY['compute']::text[], 3, 'コンテナ化したマイクロサービスを、EC2 の管理をせずに実行し、負荷に応じてタスク数を自動増減させたい。適切な組み合わせはどれか。', '{"ア":"単一 EC2 上で docker run を手動実行する","イ":"Lambda で 15 分を超える常駐プロセスを動かす","ウ":"Elastic Beanstalk のワーカー環境で cron を回す","エ":"Amazon ECS(または EKS)on AWS Fargate + Service Auto Scaling"}'::jsonb, 'エ', 'Fargate はサーバーレスなコンテナ実行基盤で、EC2 のプロビジョニング/パッチが不要。ECS/EKS の Service Auto Scaling が CloudWatch メトリクスに応じてタスク数を調整する。Lambda は最大 15 分で常駐用途には不向き。', 'generated'),
('D3', 'gen-batch-003', 77, ARRAY['storage']::text[], 2, 'オンプレの Windows ファイルサーバー(SMB、NTFS、AD 連携、DFS)を、機能を保ったままクラウドへ移行したい。適切なサービスはどれか。', '{"ア":"Amazon EFS","イ":"Amazon FSx for Windows File Server","ウ":"Amazon S3 + File Gateway","エ":"Amazon EBS Multi-Attach"}'::jsonb, 'イ', 'FSx for Windows File Server はネイティブ SMB / NTFS / Active Directory 統合 / DFS 名前空間 / VSS をサポートするマネージド Windows ファイルサーバー。EFS は Linux/NFS 向け。File Gateway はオンプレからの S3 キャッシュアクセス用途。', 'generated'),
('D3', 'gen-batch-003', 78, ARRAY['performance']::text[], 3, 'CloudFront のキャッシュヒット率を高めるための施策として適切なものはどれか。', '{"ア":"TTL を常に 0 にする","イ":"すべてのリクエストにランダムなクエリパラメータを付与する","ウ":"キャッシュキーから不要なクエリ文字列/ヘッダ/Cookie を除外し、適切な Cache-Control(max-age)をオリジンで設定する","エ":"エッジロケーションを 1 か所に限定する"}'::jsonb, 'ウ', 'キャッシュキーに含める要素が多いほどキャッシュが分散しヒット率が下がる。不要な次元を外し、オリジンで十分な max-age を返すことでエッジ再利用が増える。ランダムパラメータや TTL0 はキャッシュを無効化する。', 'generated'),
('D3', 'gen-batch-003', 79, ARRAY['database']::text[], 2, 'スキーマが頻繁に変わる半構造化データを、1 桁ミリ秒で予測可能なレイテンシ、ほぼ無限のスケールで読み書きしたい。適切なデータベースはどれか。', '{"ア":"Amazon RDS for MySQL","イ":"Amazon Redshift","ウ":"Amazon Neptune","エ":"Amazon DynamoDB"}'::jsonb, 'エ', 'DynamoDB はフルマネージドの NoSQL(キーバリュー/ドキュメント)で、スキーマレス、水平スケール、一貫した低レイテンシが特徴。RDS は固定スキーマの RDBMS、Redshift は分析用、Neptune はグラフ DB。', 'generated'),
('D3', 'gen-batch-003', 80, ARRAY['compute']::text[], 2, 'Auto Scaling のターゲット追跡スケーリングで最も一般的に用いられ、Web 層の負荷に追従しやすいメトリクスはどれか。', '{"ア":"平均 CPU 使用率、または ALB のターゲットあたりリクエスト数(RequestCountPerTarget)","イ":"インスタンスのブートボリュームの空き容量","ウ":"リージョンの API 呼び出し回数","エ":"IAM ポリシーの数"}'::jsonb, 'ア', 'ターゲット追跡は「平均 CPU 50%」や「ターゲットあたり 1,000 リクエスト/分」のような目標値を維持するように台数を調整する。Web 層では CPU 使用率か RequestCountPerTarget が代表的。ディスク空きや API 回数は負荷指標として不適。', 'generated'),
('D3', 'gen-batch-003', 81, ARRAY['network']::text[], 3, 'レイテンシーベースルーティング(Route 53)の動作として正しいものはどれか。', '{"ア":"地理的な国・大陸に基づいて固定的に振り分ける","イ":"各レコードに設定した重みの比率で振り分ける","ウ":"複数リージョンに同一サービスを配置し、問い合わせ元から見て最も低レイテンシのリージョンのレコードを返す","エ":"常にプライマリリージョンを返し、障害時のみセカンダリを返す"}'::jsonb, 'ウ', 'レイテンシーベースルーティングは、AWS が測定しているネットワークレイテンシに基づき、リゾルバから最速のリージョンのエンドポイントを返す。地理ベースは地域固定、加重は比率配分、フェイルオーバーは冗長切替。', 'generated'),
('D3', 'gen-batch-003', 82, ARRAY['storage']::text[], 3, '汎用 SSD(gp3)ボリュームの利点として正しいものはどれか。', '{"ア":"容量とは独立に IOPS(最大 16,000)とスループット(最大 1,000 MB/s)をプロビジョンでき、gp2 より低コストになりやすい","イ":"容量に比例してのみ IOPS が増える","ウ":"HDD ベースでシーケンシャル専用である","エ":"複数リージョンに自動レプリケーションされる"}'::jsonb, 'ア', 'gp3 はベースライン 3,000 IOPS・125 MB/s を含み、容量と切り離して性能を追加購入できる。gp2 は 3 IOPS/GB と容量連動だった。多くのワークロードで gp3 は gp2 より安く柔軟。', 'generated'),
('D3', 'gen-batch-003', 83, ARRAY['performance']::text[], 2, '大きなファイル(数 GB)を S3 へアップロードする際に、スループットと信頼性を高める推奨手法はどれか。', '{"ア":"1 回の PUT で単一リクエストとして送る","イ":"ファイルを Base64 にしてメタデータへ格納する","ウ":"S3 ではなく DynamoDB に分割保存する","エ":"マルチパートアップロードを使い、パートを並列転送する(失敗時は該当パートのみ再送)"}'::jsonb, 'エ', 'マルチパートアップロードはファイルを分割し並列アップロードするため高速で、途中失敗もパート単位で再送できる。100 MB 以上で推奨、5 GB 超では必須。単一 PUT は最大 5 GB かつ失敗時は全体やり直し。', 'generated'),
('D3', 'gen-batch-003', 84, ARRAY['compute']::text[], 3, 'Lambda の同時実行数が上限に達し、一部リクエストがスロットリング(429)されている。関数は下流の RDS も呼ぶ。適切な対策の組み合わせはどれか。', '{"ア":"関数のタイムアウトを最大にするだけ","イ":"アカウント/関数の同時実行上限引き上げを申請しつつ、RDS Proxy で接続をプールし、必要なら予約済み同時実行で下流を保護する","ウ":"メモリ割り当てを最小にする","エ":"VPC 設定を削除して RDS へ直接接続する"}'::jsonb, 'イ', 'スロットリングは同時実行の上限に起因するため、上限緩和とバースト設計を行う。一方で Lambda の急増は RDS の接続枯渇を招くため RDS Proxy でプーリングし、予約済み同時実行で下流への流量を制御する。タイムアウトやメモリ変更は本質的解決にならない。', 'generated'),
('D3', 'gen-batch-003', 85, ARRAY['database']::text[], 2, 'リードレプリカへ振り向けた読み取りで、書き込み直後のデータが反映されていないことがある。理由として正しいものはどれか。', '{"ア":"リードレプリカは非同期レプリケーションのため、レプリケーションラグにより一時的に古いデータを返すことがある","イ":"リードレプリカは書き込みも受け付けるため競合している","ウ":"リードレプリカはキャッシュのみでディスクを持たない","エ":"リードレプリカはプライマリと別リージョンにしか作れない"}'::jsonb, 'ア', 'RDS のリードレプリカは非同期複製で、負荷やネットワークに応じてラグが生じる。強い整合性が必要な読み取りはプライマリに向ける。Aurora はラグが小さい(通常ミリ秒台)が、それでも非同期である点は同じ。', 'generated'),
('D3', 'gen-batch-003', 86, ARRAY['integration']::text[], 3, '多数の SaaS / マイクロサービスからのイベントを、内容(JSON のフィールド)に応じて異なるターゲットへルーティングし、スキーマ管理もしたい。適切なサービスはどれか。', '{"ア":"Amazon SQS 標準キュー単体","イ":"Amazon Kinesis Data Streams のみ","ウ":"AWS Batch","エ":"Amazon EventBridge(イベントバスとルール、スキーマレジストリ)"}'::jsonb, 'エ', 'EventBridge はイベントバスにルール(イベントパターンによる内容ベースのフィルタ)を定義し、Lambda / SQS / Step Functions など多様なターゲットへ配信できる。SaaS パートナーイベントやスキーマレジストリも備える。SQS 単体は内容ルーティング不可。', 'generated'),
('D3', 'gen-batch-003', 87, ARRAY['network']::text[], 2, 'ALB と NLB の使い分けとして正しいものはどれか。', '{"ア":"NLB は HTTP ヘッダを見てルーティングできる","イ":"ALB は静的 IP を提供し、UDP を負荷分散できる","ウ":"L7 のパスやホストベースのルーティング、HTTP 機能が必要なら ALB。超低レイテンシや固定 IP、TCP/UDP、極端な急増なら NLB","エ":"両者に機能差はなく名称だけが違う"}'::jsonb, 'ウ', 'ALB は L7 で、パス/ホスト/ヘッダルーティング、リダイレクト、認証統合、WAF 連携が可能。NLB は L4 で、ミリ秒未満のレイテンシ、AZ ごとの静的/Elastic IP、TCP/UDP/TLS パススルー、突発的スパイクへの耐性が強み。', 'generated'),
('D3', 'gen-batch-003', 88, ARRAY['storage']::text[], 2, '多数の小さなオブジェクトへ世界中から頻繁にアクセスがあり、S3 へのアップロード自体も地理的に遠いユーザーから行われる。アップロード高速化に有効な機能はどれか。', '{"ア":"S3 バケットのバージョニング","イ":"S3 Transfer Acceleration(CloudFront エッジ経由で S3 へ転送)","ウ":"S3 オブジェクトロック","エ":"S3 リクエスタ支払い"}'::jsonb, 'イ', 'Transfer Acceleration は最寄りの CloudFront エッジでトラフィックを受け、AWS バックボーン経由で S3 へ転送するため、遠距離アップロードのスループットが向上する。バージョニングやロックはデータ保護機能で速度に無関係。', 'generated'),
('D3', 'gen-batch-003', 89, ARRAY['performance']::text[], 3, 'パフォーマンス効率の柱の観点で、まず検討すべき考え方として最も適切なものはどれか。', '{"ア":"できる限り自前で EC2 上にすべてを構築して細かく制御する","イ":"マネージドサービスやサーバーレスを活用し、差別化につながらない重労働を AWS に任せて、需要に応じて弾力的にスケールする","ウ":"常に最大サイズのインスタンスを確保しておく","エ":"スケーリングは人手による運用でまかなう"}'::jsonb, 'イ', 'Well-Architected のパフォーマンス効率では、マネージド/サーバーレスの採用、需要に追従する弾力性、実験と計測に基づく技術選定が推奨される。過剰な自前構築や固定的な大容量確保は非効率で、手動スケールは追従が遅い。', 'generated'),
('D3', 'gen-batch-003', 90, ARRAY['performance']::text[], 3, 'S3 に蓄積した大量の CSV/Parquet ログに対し、サーバーを立てずに標準 SQL でアドホック分析したい。適切なサービスはどれか。', '{"ア":"Amazon Athena(S3 上のデータに対するサーバーレスクエリ)","イ":"Amazon EMR クラスターを常時起動する","ウ":"各ファイルを RDS にインポートしてから集計する","エ":"S3 Select を使ってオブジェクトを 1 つずつ処理する"}'::jsonb, 'ア', 'Athena は Presto/Trino ベースのサーバーレスクエリサービスで、S3 のデータに Glue データカタログのスキーマを当てて標準 SQL を実行し、スキャン量に応じて課金される。Parquet 化やパーティション分割でコストと速度が改善する。常時 EMR は運用/費用が重い。', 'generated');
